-- PC Movement Rebuild / Delta iOS AutoExecute
-- Generated by tools/build_rebuild.py; edit rebuild/*.lua instead.
-- One native keyboard owner. No runtime downloads or physics writes.
-- Physics and map/emote signals still require on-device validation.

local function buildCore()
-- Pure input policy. No Roblox services, physics writes or animation assumptions.
local Core = {}
local KEY_ORDER = {"W", "A", "S", "D", "Space"}

local function finite(value)
    return type(value) == "number" and value == value and math.abs(value) < math.huge
end

function Core.chord(keys)
    local names = {}
    for _, name in ipairs(KEY_ORDER) do
        if keys[name] then names[#names + 1] = name end
    end
    return #names > 0 and table.concat(names, "+") or "-"
end

function Core.new(config)
    config = config or {}
    local self = {engaged=false, lastAir=-math.huge, lastGrid=-math.huge}
    function self:step(input, observed, now)
        local air = observed.grounded == false
        local valid = observed.alive == true and not observed.blocked
        if air and valid then self.lastAir = now end
        if observed.gridContact then self.lastGrid = now end
        local chain = valid and observed.grounded == true and observed.jumpIntent == true
            and now - self.lastAir <= 0.10
        local reverse = air and (observed.horizontalSpeed or 0) >= 1
            and (observed.forwardDot or 0) < -0.15
        local flags = {
            STANDING_GROUNDED=valid and observed.grounded == true and observed.crouched ~= true,
            CROUCH_GROUNDED=valid and observed.grounded == true and observed.crouched == true,
            AIRBORNE=valid and air,
            BHOP_AIRBORNE=valid and air and (observed.crouched == true or observed.jumpIntent == true),
            REVERSE_BHOP=valid and reverse,
            EMOTE_MOVEMENT=valid and observed.emote == true,
            GRID_CONTACT=valid and observed.gridContact == true,
            GRID_AIRBORNE=valid and air and now - self.lastGrid <= 0.18,
            LANDING_BUFFER=chain,
        }
        local lateral = air or observed.crouched == true or observed.emote == true
            or observed.gridContact == true or chain
        local primary = "STANDING_GROUNDED"
        for _, name in ipairs({"CROUCH_GROUNDED", "AIRBORNE", "BHOP_AIRBORNE",
            "REVERSE_BHOP", "EMOTE_MOVEMENT", "GRID_AIRBORNE", "GRID_CONTACT"}) do
            if flags[name] then primary = name end
        end
        if not valid then primary = "SUSPENDED" end

        local x = finite(input.x) and input.x or 0
        local z = finite(input.z) and input.z or 0
        local scale=math.max(1,math.sqrt(x*x+z*z))
        x,z=x/scale,z/scale
        local radius = math.sqrt(x*x + z*z)
        local threshold = self.engaged and 0.18 or 0.30
        self.engaged = valid and input.active == true and radius >= threshold
        local keys = {}
        if self.engaged then
            local side = x < 0 and "A" or "D"
            if config.SwapAD then side = side == "A" and "D" or "A" end
            if lateral then
                -- Physical keyboard directions remain camera-relative even in reverse.
                -- A centered thumb does not create W or synthetic forward momentum.
                if math.abs(x) >= 0.08 then keys[side] = true end
            elseif z > 0 and z >= math.abs(x) * 0.45 then
                keys.S = true
            else
                keys.W = true
                if math.abs(x) > math.max(0.08, math.max(0,-z) * 0.34) then
                    keys[side] = true
                end
            end
        end
        return {keys=keys, flags=flags, primary=primary, lateralOnly=lateral,
            intensity=math.min(1,radius), x=x, z=z}
    end
    return self
end

function Core.keys(send)
    local self = {pressed={}, events=0, failures=0}
    for _, name in ipairs(KEY_ORDER) do self.pressed[name] = false end
    local function change(name, down)
        local ok, accepted = pcall(send, name, down)
        if ok and accepted == true then
            self.pressed[name] = down
            self.events = self.events + 1
            return true
        end
        self.failures = self.failures + 1
        return false
    end
    function self:apply(desired)
        -- Remove obsolete longitudinal keys before entering a lateral-only mode.
        for _, name in ipairs({"W", "S"}) do
            if self.pressed[name] and not desired[name] then change(name,false) end
        end
        -- An A/D swap is one synchronous batch. Never queue a W+A+D sweep,
        -- insert a wait, or retain an intermediate chord for a rendered frame.
        for _, name in ipairs(KEY_ORDER) do
            if desired[name] and not self.pressed[name] then change(name,true) end
        end
        for _, name in ipairs({"A", "D", "Space"}) do
            if self.pressed[name] and not desired[name] then change(name,false) end
        end
        -- Failed releases remain pressed in the ledger until a later successful retry.
        return Core.chord(self.pressed)
    end
    return self
end

function Core.jump(config)
    config = config or {}
    local self = {held=false, pulses=0, pendingUntil=-math.huge,
        spaceUntil=-math.huge, lastPulse=-math.huge, lastIntent=-math.huge,
        manual=false, spentGround=false, lastReason="none"}
    function self:request(now)
        self.pendingUntil = now + 0.20
        self.lastIntent = now
        self.manual = true
    end
    function self:setHeld(held, now)
        if held and not self.held then self:request(now) end
        self.held = held == true
    end
    function self:hasIntent(now)
        return self.held or now <= self.pendingUntil
    end
    function self:cancel()
        self.held = false
        self.manual = false
        self.pendingUntil = -math.huge
        self.spaceUntil = -math.huge
        self.spentGround = false
    end
    function self:step(now, observed)
        if not observed.alive or observed.blocked then
            self:cancel()
            return false, "suspended"
        end
        if observed.grounded == false then self.spentGround = false end
        if now > self.pendingUntil then self.manual = false end
        local canPulse = observed.canJump ~= false and now - self.lastPulse >= 0.11
        local reason
        if canPulse and self.manual then
            reason = "manual"
        elseif canPulse and observed.grounded == true and not self.spentGround
            and self:hasIntent(now) then
            reason = observed.gridContact and config.ContactJump ~= false
                and "grid_contact" or "landing_buffer"
        end
        if reason then
            self.spaceUntil = now + 0.055
            self.lastPulse = now
            self.lastReason = reason
            self.manual = false
            self.pulses = self.pulses + 1
            if observed.grounded then self.spentGround = true end
        end
        return now < self.spaceUntil, reason
    end
    return self
end

function Core.log(capacity)
    local self = {enabled=false, size=0, next=1, entries={}, capacity=capacity or 180}
    function self:add(entry)
        if not self.enabled then return end
        self.entries[self.next] = entry
        self.next = self.next % self.capacity + 1
        self.size = math.min(self.capacity,self.size+1)
    end
    function self:read()
        local out = {}
        local start = self.size == self.capacity and self.next or 1
        for offset=0,self.size-1 do
            out[#out+1] = self.entries[(start+offset-1)%self.capacity+1]
        end
        return out
    end
    return self
end

return Core

end

local function buildKeyboardRoute()
-- Select the existing Roblox Keyboard controller; never call Player/Humanoid:Move.
local Route={}
local function globallyDisabled(controls)
    return rawget(controls,"controlsEnabled")==false or rawget(controls,"disabled")==true
end
function Route.new(services,env)
    local self={controls=services.Controls,keyboard=services.KeyboardModule,
        touchModules=services.TouchModules or {},running=false,enabled=true,
        status="not-started",restores=0,errors=0,facadeActive=false,generation=0}
    local originalModule,originalController,previousSwitch,wrappedSwitch
    local hadOwnSwitch=false
    local previousIndex,indexWrapper
    local uis=services.UserInputService
    local function activate(fn)
        self.facadeActive=true
        local ok,message=pcall(fn)
        self.facadeActive=false
        if not ok then self.errors=self.errors+1 self.status=tostring(message) end
        return ok
    end
    local function installFacade()
        if type(hookmetamethod)~="function" or not uis then return end
        local closure=type(newcclosure)=="function" and newcclosure or function(fn) return fn end
        indexWrapper=closure(function(object,key)
            -- Activation is synchronous and scoped. PlayerModule may inherit the
            -- executor's caller identity, so caller identity cannot gate this read.
            if self.facadeActive and object==uis then
                if key=="KeyboardEnabled" or key=="MouseEnabled" then return true end
                if key=="TouchEnabled" or key=="GamepadEnabled" then return false end
            end
            return previousIndex(object,key)
        end)
        local ok,value=pcall(function() return hookmetamethod(game,"__index",indexWrapper) end)
        if ok and type(value)=="function" then previousIndex=value else indexWrapper=nil end
    end
    local function discover()
        if self.controls and self.keyboard then return true end
        local player=services.player
        local scripts=player and player:FindFirstChild("PlayerScripts")
        local playerScript=scripts and scripts:FindFirstChild("PlayerModule")
        if not playerScript then self.status="PlayerModule-missing" return false end
        local ok,module=pcall(require,playerScript)
        if not ok or type(module)~="table" then self.status="PlayerModule-unavailable" return false end
        self.playerModule=module
        local good,controls=pcall(function() return module:GetControls() end)
        if not good or type(controls)~="table" then self.status="controls-unavailable" return false end
        self.controls=controls
        local controlScript=playerScript:FindFirstChild("ControlModule")
        local keyboardScript=controlScript and controlScript:FindFirstChild("Keyboard")
        local loaded,keyboard=pcall(function() return keyboardScript and require(keyboardScript) end)
        if not loaded or type(keyboard)~="table" then self.status="Keyboard-module-unavailable" return false end
        self.keyboard=keyboard
        for _,name in ipairs({"TouchThumbstick","DynamicThumbstick"}) do
            local child=controlScript:FindFirstChild(name)
            if child then
                local success,touch=pcall(require,child)
                if success and type(touch)=="table" then self.touchModules[#self.touchModules+1]=touch end
            end
        end
        return true
    end
    local function isTouch(module)
        for _,touch in ipairs(self.touchModules) do if touch==module then return true end end
        return false
    end
    function self:IsReady()
        local c=self.controls
        local active=c and rawget(c,"activeController")
        return self.running and self.enabled and c~=nil and not globallyDisabled(c)
            and rawget(c,"activeControlModule")==self.keyboard
            and type(active)=="table" and rawget(active,"enabled")==true
    end
    function self:Refresh()
        if not self.running or not self.enabled or not self.controls then return end
        local c=self.controls
        if globallyDisabled(c) then self.status="game-controls-disabled" return end
        local current=rawget(c,"activeControlModule")
        -- Do not override vehicle, scripted, nil/menu or unrelated controllers.
        if current~=self.keyboard and not isTouch(current) then self.status="other-controller" return end
        local before=rawget(c,"activeController")
        local wasEnabled=type(before)=="table" and rawget(before,"enabled")==true
        activate(function()
            if current~=self.keyboard then
                previousSwitch(c,self.keyboard)
                self.restores=self.restores+1
            end
            local active=rawget(c,"activeController")
            if rawget(c,"activeControlModule")==self.keyboard and type(active)=="table"
                and rawget(active,"enabled")~=true and type(active.Enable)=="function" then
                active:Enable(true)
            end
        end)
        if self:IsReady() and (current~=self.keyboard or rawget(c,"activeController")~=before or not wasEnabled) then
            self.generation=self.generation+1
        end
        self.status=self:IsReady() and "keyboard-ready" or "keyboard-not-enabled"
    end
    function self:Start()
        if self.running then return self:IsReady() end
        if not discover() then return false end
        local c=self.controls
        originalModule=rawget(c,"activeControlModule")
        originalController=rawget(c,"activeController")
        hadOwnSwitch=rawget(c,"SwitchToController")~=nil
        previousSwitch=c.SwitchToController
        if type(previousSwitch)~="function" then self.status="SwitchToController-missing" return false end
        installFacade()
        self.running=true
        wrappedSwitch=function(owner,module,...)
            if owner==c and self.running and self.enabled and isTouch(module) then
                if globallyDisabled(c) then return previousSwitch(owner,module,...) end
                if rawget(c,"activeControlModule")==self.keyboard then return nil end
                local arguments={...}
                activate(function()
                    previousSwitch(owner,self.keyboard,(table.unpack or unpack)(arguments))
                end)
                self.generation=self.generation+1
                return nil
            end
            return previousSwitch(owner,module,...)
        end
        rawset(c,"SwitchToController",wrappedSwitch)
        -- Explicit initial selection also works when PlayerModule starts with nil.
        if not globallyDisabled(c) then
            activate(function() previousSwitch(c,self.keyboard) end)
            self.generation=self.generation+1
        end
        self:Refresh()
        return self:IsReady()
    end
    function self:SetEnabled(value)
        self.enabled=value~=false
        if not self.enabled and self.running and originalModule then
            pcall(previousSwitch,self.controls,originalModule)
        elseif self.enabled then self:Refresh() end
    end
    function self:GetState()
        return {ready=self:IsReady(),status=self.status,facadeActive=self.facadeActive,
            facadeInstalled=previousIndex~=nil,restores=self.restores,errors=self.errors}
    end
    function self:Stop()
        self.running=false
        self.facadeActive=false
        local c=self.controls
        if c and rawget(c,"SwitchToController")==wrappedSwitch then
            rawset(c,"SwitchToController",hadOwnSwitch and previousSwitch or nil)
        end
        if c and previousSwitch and originalModule and rawget(c,"activeControlModule")==self.keyboard then
            pcall(previousSwitch,c,originalModule)
            if originalController and rawget(c,"activeController")==originalController
                and globallyDisabled(c) and type(originalController.Enable)=="function" then
                pcall(originalController.Enable,originalController,false)
            end
        end
        if previousIndex and type(hookmetamethod)=="function" then
            local owned=false
            if type(getrawmetatable)=="function" then
                local ok,meta=pcall(getrawmetatable,game)
                owned=ok and type(meta)=="table" and rawget(meta,"__index")==indexWrapper
            end
            if owned then pcall(function() hookmetamethod(game,"__index",previousIndex) end) end
            -- A later hook may delegate to this inactive wrapper. Retain its
            -- predecessor; never remove someone else's hook or turn a chain nil.
        end
    end
    return self
end
return Route

end

local function buildControls()
-- Original V3/V6 control names, sprites and layout. No movement/key logic here.
local Controls={}
local GUI_NAME="PCKeyboardTouchBridgeV52Overlay"
local function create(class,name,parent,properties)
    local object=Instance.new(class)
    object.Name=name
    for key,value in pairs(properties or {}) do object[key]=value end
    object.Parent=parent
    return object
end
local function round(object)
    create("UICorner","UICorner",object,{CornerRadius=UDim.new(1,0)})
    create("UIStroke","UIStroke",object,{Thickness=3,Transparency=1})
end
function Controls.new(services)
    local self={offset=Vector2.zero,target=Vector2.zero,auto={},stopped=false}
    local pg=services.playerGui
    local gui=pg:FindFirstChild(GUI_NAME)
    local stick=gui and gui:FindFirstChild("PCJoystick",true)
    local knob=stick and stick:FindFirstChild("Knob")
    local jump=gui and gui:FindFirstChild("PCJump",true)
    local reused=gui and stick and knob and jump
    if not reused then
        if gui then gui:Destroy() end
        gui=create("ScreenGui",GUI_NAME,pg,{ResetOnSpawn=false,IgnoreGuiInset=true,DisplayOrder=10020})
        stick=create("TextButton","PCJoystick",gui,{Text="",AutoButtonColor=false,Active=true,
            BackgroundColor3=Color3.fromRGB(55,55,55),BackgroundTransparency=1,
            BorderSizePixel=0,AnchorPoint=Vector2.new(0,0),ZIndex=20})
        round(stick)
        knob=create("Frame","Knob",stick,{BackgroundColor3=Color3.fromRGB(205,205,205),
            BackgroundTransparency=1,BorderSizePixel=0,AnchorPoint=Vector2.new(0.5,0.5),
            Position=UDim2.fromScale(0.5,0.5),ZIndex=21})
        create("UICorner","UICorner",knob,{CornerRadius=UDim.new(1,0)})
        jump=create("TextButton","PCJump",gui,{Text="",AutoButtonColor=false,Active=true,
            Font=Enum.Font.GothamBold,TextSize=35,TextColor3=Color3.fromRGB(225,225,225),
            BackgroundColor3=Color3.fromRGB(55,55,55),BackgroundTransparency=1,
            BorderSizePixel=0,AnchorPoint=Vector2.new(0,0),ZIndex=20})
        round(jump)
    end
    self.gui,self.joystick,self.knob,self.jump=gui,stick,knob,jump
    gui:SetAttribute("PCMovementRebuild",true)
    local outer=stick:FindFirstChild("RobloxThumbstickOuter") or create("ImageLabel","RobloxThumbstickOuter",stick,{
        BackgroundTransparency=1,Image="rbxasset://textures/ui/TouchControlsSheet.png",
        ImageRectOffset=Vector2.new(0,0),ImageRectSize=Vector2.new(220,220),
        Size=UDim2.fromScale(1,1),Position=UDim2.fromOffset(0,0),ZIndex=stick.ZIndex,Active=false})
    if not knob:FindFirstChild("RobloxThumbstickStick") then
        create("ImageLabel","RobloxThumbstickStick",knob,{BackgroundTransparency=1,
            Image="rbxasset://textures/ui/TouchControlsSheet.png",ImageRectOffset=Vector2.new(220,0),
            ImageRectSize=Vector2.new(111,111),Size=UDim2.fromScale(1,1),
            Position=UDim2.fromScale(0,0),ZIndex=knob.ZIndex,Active=false})
    end
    self.jumpImage=jump:FindFirstChild("RobloxJumpButton") or create("ImageLabel","RobloxJumpButton",jump,{
        BackgroundTransparency=1,Image="rbxasset://textures/ui/Input/TouchControlsSheetV2.png",
        ImageRectOffset=Vector2.new(1,146),ImageRectSize=Vector2.new(144,144),Size=UDim2.fromScale(1,1),
        Position=UDim2.fromOffset(0,0),ZIndex=jump.ZIndex,Active=false})
    local function layoutFor(viewport)
        local size=math.min(viewport.X,viewport.Y)<=500 and 70 or 120
        return size, size==70 and UDim2.new(0,size/2-10,1,-size-20)
            or UDim2.new(0,size/2,1,-size*1.75),
            UDim2.new(1,-(size*1.5-10),1,size==70 and -size-20 or -size*1.75)
    end
    local function autoLayout(object,size,position)
        local last=self.auto[object]
        if last and (object.Size~=last.size or object.Position~=last.position) then
            self.auto[object]=nil -- External layout editor owns it from now on.
            return
        end
        if not last then return end
        object.Size=UDim2.fromOffset(size,size)
        object.Position=position
        self.auto[object]={size=object.Size,position=object.Position}
    end
    local viewport=services.Workspace.CurrentCamera and services.Workspace.CurrentCamera.ViewportSize
        or Vector2.new(896,414)
    local size,stickPosition,jumpPosition=layoutFor(viewport)
    for _,row in ipairs({{stick,stickPosition},{jump,jumpPosition}}) do
        local object,position=row[1],row[2]
        if not reused or (object.Size==UDim2.fromOffset(size,size) and object.Position==position) then
            object.Size=UDim2.fromOffset(size,size)
            object.Position=position
            self.auto[object]={size=object.Size,position=object.Position}
        end
    end
    if not reused then knob.Size=UDim2.fromOffset(size/2,size/2) end
    function self:Layout(newViewport)
        local newSize,stickPos,jumpPos=layoutFor(newViewport)
        local wasAuto=self.auto[stick]~=nil
        autoLayout(stick,newSize,stickPos)
        autoLayout(jump,newSize,jumpPos)
        if wasAuto and self.auto[stick] then knob.Size=UDim2.fromOffset(newSize/2,newSize/2) end
        -- Image scales with its externally resized parent, not a stale pixel size.
        outer.Size=UDim2.fromScale(1,1)
    end
    function self:Contains(position)
        if self.stopped or not gui.Parent or not gui.Enabled then return nil end
        for _,row in ipairs({{stick,"joystick"},{jump,"jump"}}) do
            local object=row[1]
            if object.Parent and object.Visible then
                local p,s=object.AbsolutePosition,object.AbsoluteSize
                if position.X>=p.X and position.X<=p.X+s.X and position.Y>=p.Y and position.Y<=p.Y+s.Y then
                    return row[2]
                end
            end
        end
        return nil
    end
    function self:SetKnob(offset)
        local limit=math.max(1,math.min(stick.AbsoluteSize.X,stick.AbsoluteSize.Y)*0.42)*0.62
        self.target=offset.Magnitude>limit and offset.Unit*limit or offset
    end
    function self:Step(dt)
        if self.stopped or not knob.Parent then return end
        local alpha=1-math.exp(-math.max(0,math.min(0.05,dt or 1/60))/0.040)
        self.offset=self.offset:Lerp(self.target,alpha)
        if (self.offset-self.target).Magnitude<0.06 then self.offset=self.target end
        knob.Position=UDim2.fromOffset(stick.AbsoluteSize.X/2+self.offset.X,stick.AbsoluteSize.Y/2+self.offset.Y)
    end
    function self:ResetKnob()
        self.offset,self.target=Vector2.zero,Vector2.zero
        knob.Position=UDim2.fromScale(0.5,0.5)
    end
    function self:SetJumpPressed(value)
        if self.jumpImage and self.jumpImage.Parent then
            self.jumpImage.ImageRectOffset=Vector2.new(value and 146 or 1,146)
        end
    end
    function self:Stop(retain)
        self:ResetKnob()
        self:SetJumpPressed(false)
        self.stopped=true
        if not retain then gui:Destroy() end
    end
    self:ResetKnob()
    return self
end
return Controls

end

local function buildGridSensor()
-- Observation only: broader discovery is never a collider, force or movement motor.
local Grid = {}
local WORDS = {fence=true,fences=true,railing=true,railings=true,rail=true,
    handrail=true,grate=true,grid=true,grade=true,lattice=true,balustrade=true}
local function named(instance)
    local text = (instance.Name or ""):gsub("(%l)(%u)","%1 %2"):lower()
    for token in text:gmatch("%a+") do if WORDS[token] then return true end end
    return false
end
local function isBodyOfCharacter(part)
    local node=part.Parent
    for _=1,4 do
        if not node then break end
        if node.FindFirstChildOfClass and node:FindFirstChildOfClass("Humanoid") then return true end
        node=node.Parent
    end
    return false
end
local function broadFloor(part)
    local s=part.Size
    return s.Y <= 1 and s.X > 3 and s.Z > 3
end
local function barKind(part)
    if part.ClassName ~= "Part" then return nil end
    local s=part.Size
    local small,large=math.min(s.X,s.Z),math.max(s.X,s.Z)
    if s.Y >= 1.25 and small <= 0.65 and large <= 1 and s.Y >= large*2.5 then
        return "upright"
    end
    if s.Y <= 0.65 and small <= 0.65 and large >= 2.5 then return "horizontal" end
    return nil
end
local function parallel(a,b,kind)
    local av=a.CFrame and (kind=="upright" and a.CFrame.UpVector or
        (a.Size.X>a.Size.Z and a.CFrame.RightVector or a.CFrame.LookVector))
    local bv=b.CFrame and (kind=="upright" and b.CFrame.UpVector or
        (b.Size.X>b.Size.Z and b.CFrame.RightVector or b.CFrame.LookVector))
    if not av or not bv then return false end
    return math.abs(av.X*bv.X+av.Y*bv.Y+av.Z*bv.Z) > 0.94
end
local function repeatedRow(anchor,bars)
    local a,kind=anchor.part,anchor.kind
    local axis=kind=="upright" and a.CFrame.UpVector or
        (a.Size.X>a.Size.Z and a.CFrame.RightVector or a.CFrame.LookVector)
    local basis,best
    for _,candidate in ipairs(bars) do
        local b=candidate.part
        if b~=a and kind==candidate.kind and b.Parent==a.Parent and parallel(a,b,kind) then
            local x,y,z=b.Position.X-a.Position.X,b.Position.Y-a.Position.Y,b.Position.Z-a.Position.Z
            local squared=x*x+y*y+z*z
            if squared>=0.0225 and squared<=36 and math.abs(x*axis.X+y*axis.Y+z*axis.Z)<=0.75
                and (not best or squared<best) then
                local length=math.sqrt(squared)
                basis={x/length,y/length,z/length};best=squared
            end
        end
    end
    if not basis then return false end
    local projections={0}
    for _,candidate in ipairs(bars) do
        local b=candidate.part
        if b~=a and kind==candidate.kind and b.Parent==a.Parent and parallel(a,b,kind) then
            local x,y,z=b.Position.X-a.Position.X,b.Position.Y-a.Position.Y,b.Position.Z-a.Position.Z
            local projection=x*basis[1]+y*basis[2]+z*basis[3]
            local perpendicular=math.max(0,x*x+y*y+z*z-projection*projection)
            if math.abs(projection)<=6 and perpendicular<=0.0625 then
                local distinct=true
                for _,value in ipairs(projections) do
                    if math.abs(projection-value)<0.15 then distinct=false break end
                end
                if distinct then projections[#projections+1]=projection end
                if #projections>=3 then return true end
            end
        end
    end
    return false
end

function Grid.new(services,config)
    config=config or {}
    local self={character=nil,root=nil,bodies={},nearby={},inferred={},
        lastBroad=-math.huge,lastNarrow=-math.huge,queries=0,narrowReads=0,
        snapshot={contact=false,nearby=false,evidence="none"},stopped=false}
    local world=services.Workspace
    local overlap=OverlapParams.new()
    overlap.FilterType=Enum.RaycastFilterType.Exclude
    overlap.MaxParts=48
    pcall(function() overlap.RespectCanCollide=true end)
    local groups={}
    local function valid(part)
        return part and part.Parent and part.IsA and part:IsA("BasePart")
            and part.CanCollide and not isBodyOfCharacter(part)
    end
    local function label(part)
        if not valid(part) or broadFloor(part) or part:IsA("TrussPart") then return nil end
        local node=part
        for _=1,3 do
            if not node or node==world then break end
            if services.CollectionService then
                for _,tag in ipairs(config.GridTags or {"Fence","Railing","Grid"}) do
                    if services.CollectionService:HasTag(node,tag) then return "tag:"..tag end
                end
            end
            if named(node) then return "name" end
            node=node.Parent
        end
        if config.AllowInferredGrids ~= false and self.inferred[part] then return "repeated-bars" end
        return nil
    end
    local function collides(body,part,now)
        if not body.CanCollide or not part.CanCollide then return false end
        local a,b=body.CollisionGroup,part.CollisionGroup
        local key=a.."\0"..b
        local entry=groups[key]
        if entry and now-entry.at<0.5 then return entry.value end
        local ok,value=pcall(function()
            return services.PhysicsService:CollisionGroupsAreCollidable(a,b)
        end)
        local allowed=ok and value==true
        groups[key]={at=now,value=allowed}
        return allowed
    end
    function self:Bind(character,humanoid,root)
        self.character=character
        self.root=root
        self.bodies={}
        if character then
            for _,part in ipairs(character:GetChildren()) do
                if #self.bodies>=24 then break end
                if part.IsA and part:IsA("BasePart") then self.bodies[#self.bodies+1]=part end
            end
        end
        overlap.FilterDescendantsInstances=character and {character} or {}
        self.inferred={}
        self.nearby={}
        groups={}
        self.lastBroad=-math.huge
        self.lastNarrow=-math.huge
        self.snapshot={contact=false,nearby=false,evidence="none"}
    end
    function self:ContactNow(now)
        local state={contact=false,nearby=next(self.nearby)~=nil,evidence="none",at=now}
        if self.stopped or not self.root or not self.character then return state end
        local checked,bodyReads=0,0
        for _,body in ipairs(self.bodies) do
            if body.Parent==self.character and body.CanCollide then
                bodyReads=bodyReads+1
                if bodyReads>8 then break end
                self.narrowReads=self.narrowReads+1
                local ok,parts=pcall(function() return body:GetTouchingParts() end)
                if ok then
                    for _,part in ipairs(parts) do
                        checked=checked+1
                        if checked>48 then return state end
                        local evidence=label(part)
                        if evidence and collides(body,part,now) then
                            state.contact=true
                            state.part=part
                            state.body=body
                            state.evidence=evidence
                            return state
                        end
                    end
                end
            end
        end
        return state
    end
    function self:Sample(now,active)
        if self.stopped or not self.root or not active then
            self.snapshot={contact=false,nearby=false,evidence="none",at=now}
            return self.snapshot
        end
        if now-self.lastBroad>=1/12 then
            self.lastBroad=now
            self.queries=self.queries+1
            overlap.CollisionGroup=self.root.CollisionGroup
            local ok,parts=pcall(function()
                return world:GetPartBoundsInBox(self.root.CFrame,
                    Vector3.new(8,math.max(7,self.root.Size.Y+4),8),overlap)
            end)
            self.nearby={}
            self.inferred={}
            if ok then
                -- Only local candidates are compared, capped at 48; no map traversal.
                local bars={}
                for i,part in ipairs(parts) do
                    if i>48 then break end
                    if valid(part) then
                        local kind=barKind(part)
                        if kind then bars[#bars+1]={part=part,kind=kind} end
                    end
                end
                for _,a in ipairs(bars) do
                    if repeatedRow(a,bars) then self.inferred[a.part]=true end
                end
                for i,part in ipairs(parts) do
                    if i>48 then break end
                    local evidence=label(part)
                    if evidence then self.nearby[part]=evidence end
                end
            end
        end
        if now-self.lastNarrow>=1/20 then
            self.lastNarrow=now
            self.snapshot=self:ContactNow(now)
        end
        self.snapshot.nearby=next(self.nearby)~=nil
        return self.snapshot
    end
    function self:Stop()
        self.stopped=true
        self:Bind(nil,nil,nil)
    end
    return self
end
return Grid

end

local function buildCameraGate()
-- Gate control fingers by identity, not screen halves. Never edit camera CFrame.
local Gate={}
function Gate.new(getController,owns)
    local self={controller=nil,hooks={},blocked={},methods=0,errors=0}
    function self:Restore(preserveTouches)
        for i=#self.hooks,1,-1 do
            local h=self.hooks[i]
            if rawget(h.owner,h.name)==h.wrapper then rawset(h.owner,h.name,h.previous) end
        end
        self.hooks={}
        if not preserveTouches then self.blocked={} end
        self.methods=0
    end
    function self:Refresh()
        local controller=getController()
        if controller==self.controller then return end
        self:Restore(true)
        self.controller=controller
        if type(controller)~="table" then return end
        for _,name in ipairs({"OnInputBegan","OnInputChanged","OnInputEnded"}) do
            local original=controller[name]
            if type(original)=="function" then
                local previous=rawget(controller,name)
                local wrapper=function(owner,input,...)
                    if owner==controller then
                        if name=="OnInputBegan" then
                            if owns(input,true) then self.blocked[input]=true return nil end
                        elseif self.blocked[input] or owns(input,false) then
                            self.blocked[input]=true
                            if name=="OnInputEnded" then self.blocked[input]=nil end
                            return nil
                        end
                    end
                    return original(owner,input,...)
                end
                rawset(controller,name,wrapper)
                self.hooks[#self.hooks+1]={owner=controller,name=name,previous=previous,wrapper=wrapper}
                self.methods=self.methods+1
            end
        end
    end
    function self:Stop() self:Restore(false) self.controller=nil end
    return self
end
return Gate

end

local function buildRuntime()
local Runtime={}
local BIND="__PCMovementRebuild"
local GUI="PCKeyboardTouchBridgeV52Overlay"
local CROUCH={"Crouching","Crouched","IsCrouching","IsCrouched"}
local EMOTE={"IsEmoting","Emoting","EmotePlaying","PlayingEmote","DoingEmote"}

local function defaultServices()
    local services={GameId=game.GameId}
    for _,name in ipairs({"Players","RunService","UserInputService","VirtualInputManager",
        "Workspace","CollectionService","PhysicsService","HttpService","GuiService"}) do
        services[name]=game:GetService(name)
    end
    services.player=services.Players.LocalPlayer
    services.playerGui=services.player:WaitForChild("PlayerGui")
    return services
end
local function disconnect(list)
    for _,connection in ipairs(list) do pcall(function() connection:Disconnect() end) end
end
local function enumName(value)
    local ok,name=pcall(function() return value.Name end)
    return ok and name or tostring(value)
end

function Runtime.Start(modules,config,services,env)
    config=config or {}
    services=services or defaultServices()
    env=env or getgenv()
    if config.OnlyEvade~=false and services.GameId~=3647333358 then
        error("[PC Movement Rebuild] This configuration targets Evade. No controls were changed.")
    end
    local player,pg=services.player,services.playerGui
    local run,uis=services.RunService,services.UserInputService
    local now=services.Clock or os.clock
    local prior=env.PCMovementRebuild
    if type(prior)=="table" and type(prior.Stop)=="function" then prior.Stop(true) end

    -- Snapshot presentation before a legacy composite Stop destroys its overlay.
    local oldGui=pg:FindFirstChild(GUI)
    local migrated
    if oldGui and oldGui:GetAttribute("PCMovementRebuild")~=true then
        pcall(function() migrated=oldGui:Clone() end)
    end

    -- Cancel old recovery watchers before removing any overlay. Do not load them.
    for _,version in ipairs({"V2","V3","V31"}) do
        env["__PCMovementAssist"..version.."Token"]=nil
        local old=env["PCMovementAssist"..version]
        if type(old)=="table" and type(old.Stop)=="function" then pcall(old.Stop) end
    end
    local cleanupErrors={}
    for _,name in ipairs({"__LegacyGridContactAssistV1Cleanup","__PCModeLockCleanup",
        "__PCKeyboardTouchBridgeV52Cleanup","__PCKeyboardTouchBridgeV5Cleanup",
        "__PCIndependentJoystickCleanup","__PCSelectiveWASDCleanup","__PCClassicNativeKeysV3Cleanup",
        "__PCClassicNativeKeysCleanup","__PCClassicWASDCleanup","__PCCrouchToggleV59Cleanup",
        "__PCCameraTouchRightHalfGateV5Cleanup","__PCKeyboardControllerWakeV5Cleanup",
        "__PCRobloxNativeVisualV5Cleanup","__PCRobloxCleanVisualV5Cleanup"}) do
        if type(env[name])=="function" then
            local ok,message=pcall(env[name])
            if not ok then cleanupErrors[#cleanupErrors+1]=name..": "..tostring(message) end
        end
    end
    env.LegacyGridContactAssistV1=nil -- V3.1's cleanup had a mismatched version guard.
    for _,name in ipairs({"__LegacyGridContactAssistV1","__PCKeyboardTouchBridgeV52",
        "__PCModeLockV5Watch","__PCCameraTouchRightHalfGateV5","__PCKeyboardControllerWakeV5",BIND}) do
        pcall(function() run:UnbindFromRenderStep(name) end)
    end
    if migrated then
        if not pg:FindFirstChild(GUI) then migrated.Parent=pg else migrated:Destroy() end
    end

    local Core=modules.Core
    local policy=Core.new(config)
    local jump=Core.jump(config)
    local log=Core.log(180)
    log.enabled=config.Diagnostics==true
    local presentation=modules.Controls.new(services)
    local route=modules.KeyboardRoute.new(services,env)
    local grid=modules.GridSensor.new(services,config)
    local connections,charConnections={},{}
    local running,enabled,focused=true,true,true
    local movementTouch,movementCenter,movementRadius=nil,nil,46
    local jumpTouches,controlTouches={},{}
    local analogX,analogZ=0,0
    local character,humanoid,root
    local valueObjects,tracks={},{}
    local currentAnimator,animatorConnection
    local standIndicator
    local lastMaintenance,lastIndicator,lastLog=-math.huge,-math.huge,-math.huge
    local lastResult,lastObservation,lastChord=nil,nil,"-"
    local lastSpeed,lastSpeedTime=nil,nil
    local layoutSaved={}
    local provider=config.StateProvider
    local ticks,maxTickMS,changes=0,0,0
    local senderFailures=0
    local routeGeneration=-1
    local replayPending=false
    local ledger=Core.keys(function(key,down)
        local ok=pcall(function()
            services.VirtualInputManager:SendKeyEvent(down,Enum.KeyCode[key],false,game)
        end)
        if not ok then senderFailures=senderFailures+1 end
        return ok
    end)
    -- A failed Stop release is retained for the next start; no delayed old task
    -- is allowed to release keys belonging to a newer runtime.
    if type(env.__PCMovementPendingRelease)=="table" then
        for key,held in pairs(env.__PCMovementPendingRelease) do
            if held then ledger.pressed[key]=true end
        end
        ledger:apply({})
        env.__PCMovementPendingRelease=nil
    end
    local function connect(signal,fn,list)
        if signal then
            local connection=signal:Connect(fn)
            local target=list or connections
            target[#target+1]=connection
            return connection
        end
    end
    local function event(kind,details)
        if not log.enabled then return end
        details=details or {}
        details.kind,details.time=kind,now()
        log:add(details)
    end
    local function clearInput()
        movementTouch,movementCenter=nil,nil
        analogX,analogZ=0,0
        jumpTouches,controlTouches={},{}
        jump:cancel()
        policy.engaged=false
        presentation:ResetKnob()
        presentation:SetJumpPressed(false)
        ledger:apply({})
    end
    local function releaseTouch(input,cancelled)
        controlTouches[input]=nil
        if input==movementTouch then
            movementTouch,movementCenter=nil,nil
            analogX,analogZ=0,0
            policy.engaged=false
            presentation:ResetKnob()
        end
        if jumpTouches[input] then
            jumpTouches[input]=nil
            local held=next(jumpTouches)~=nil
            jump:setHeld(held,now())
            if cancelled and not held then jump:cancel() end
            presentation:SetJumpPressed(held)
        end
    end
    local function cacheValue(object)
        if object:IsA("BoolValue") then
            for _,names in ipairs({CROUCH,EMOTE}) do
                for _,name in ipairs(names) do
                    if object.Name==name then valueObjects[name]=object end
                end
            end
        end
    end
    local allowedAnimations={}
    for key,value in pairs(config.EmoteAnimationIds or {}) do
        local id=type(value)=="boolean" and key or value
        allowedAnimations[tostring(id):match("%d+$") or tostring(id)]=true
    end
    local function attachAnimator()
        local animator=humanoid and humanoid:FindFirstChildOfClass("Animator")
        if animator==currentAnimator then return end
        if animatorConnection then animatorConnection:Disconnect() end
        currentAnimator=animator
        tracks={}
        if animator then
            local ok,list=pcall(function() return animator:GetPlayingAnimationTracks() end)
            if ok then for _,track in ipairs(list) do tracks[track]=true end end
            animatorConnection=connect(animator.AnimationPlayed,function(track) tracks[track]=true end,charConnections)
        end
    end
    local function bindCharacter(char)
        clearInput()
        disconnect(charConnections);charConnections={}
        currentAnimator,animatorConnection=nil,nil
        character=char
        humanoid=char and char:FindFirstChildOfClass("Humanoid") or nil
        root=char and char:FindFirstChild("HumanoidRootPart") or nil
        valueObjects,tracks={},{}
        if char then
            for _,object in ipairs(char:GetDescendants()) do cacheValue(object) end
            connect(char.DescendantAdded,function(object)
                cacheValue(object)
                if object.Name=="HumanoidRootPart" or object:IsA("Humanoid")
                    or (object:IsA("BasePart") and object.Parent==char) then
                    humanoid=char:FindFirstChildOfClass("Humanoid")
                    root=char:FindFirstChild("HumanoidRootPart")
                    grid:Bind(char,humanoid,root)
                end
                if object:IsA("Animator") or object:IsA("Humanoid") then attachAnimator() end
            end,charConnections)
        end
        attachAnimator()
        grid:Bind(char,humanoid,root)
        policy=Core.new(config)
        lastSpeed,lastSpeedTime=nil,nil
        event("character_bound",{present=char~=nil})
    end
    local function readFlag(names)
        for _,object in ipairs({character or false,humanoid or false,player}) do
            if object then
                for _,name in ipairs(names) do
                    local value=object:GetAttribute(name)
                    if type(value)=="boolean" then return value,"attribute:"..object.Name.."."..name end
                end
            end
        end
        for _,name in ipairs(names) do
            local value=valueObjects[name]
            if value and value.Parent then return value.Value,"BoolValue:"..name end
        end
        return nil,"unknown"
    end
    local function stateSignals(t)
        local crouched,crouchSource=readFlag(CROUCH)
        local emote,emoteSource=readFlag(EMOTE)
        if provider then
            local ok,value=pcall(provider,{character=character,humanoid=humanoid,root=root,player=player})
            if ok and type(value)=="table" then
                if type(value.crouched)=="boolean" then crouched,crouchSource=value.crouched,"provider" end
                if type(value.emote)=="boolean" then emote,emoteSource=value.emote,"provider" end
            elseif not ok then event("state_provider_error",{message=tostring(value)}) end
        end
        if t-lastIndicator>=0.5 then
            lastIndicator=t
            local controlsGui=pg:FindFirstChild("ControlsGui",true)
            local frame=controlsGui and controlsGui:FindFirstChild("PCFrame",true)
            standIndicator=frame and frame:FindFirstChild("Stand",true)
        end
        if crouched==nil and config.UseLegacyStandIndicator~=false and standIndicator and standIndicator.Parent
            and standIndicator:IsA("GuiObject") then
            crouched,crouchSource=standIndicator.Visible,"ControlsGui/PCFrame/Stand.Visible (convention)"
        end
        if emote==nil and next(allowedAnimations) then
            local playing=false
            for track in pairs(tracks) do
                if not track.IsPlaying then tracks[track]=nil
                elseif track.Animation then
                    local id=tostring(track.Animation.AnimationId):match("%d+$")
                    if id and allowedAnimations[id] then playing=true end
                end
            end
            emote,emoteSource=playing,"configured-animation-ids"
        end
        return crouched,crouchSource,emote,emoteSource
    end
    local function getCameraController()
        if services.GetCameraController then return services.GetCameraController() end
        local module=route.playerModule
        if type(module)~="table" then return nil end
        local ok,cameras=pcall(function() return module:GetCameras() end)
        if not ok or type(cameras)~="table" then return nil end
        local active=rawget(cameras,"activeCameraController")
        if active then return active end
        if type(cameras.GetActiveCameraController)=="function" then return cameras:GetActiveCameraController() end
        return nil
    end
    local gate=modules.CameraGate.new(getCameraController,function(input,began)
        if input.UserInputType~=Enum.UserInputType.Touch or not enabled then return false end
        return controlTouches[input]==true or (began and presentation:Contains(input.Position)~=nil)
    end)
    local function observe(t)
        local valid=humanoid and root and root.Parent and humanoid.Health>0
        local state=valid and enumName(humanoid:GetState()) or "Missing"
        local airborne=state=="Jumping" or state=="Freefall"
        local grounded=valid and not airborne and humanoid.FloorMaterial~=Enum.Material.Air or false
        local blocked=not enabled or not focused or not route:IsReady() or uis:GetFocusedTextBox()~=nil
            or (valid and (humanoid.Sit or humanoid.PlatformStand or root.Anchored))
            or state=="Swimming" or state=="Dead" or state=="Ragdoll" or state=="Physics"
        if services.GuiService then
            local ok,opened=pcall(function() return services.GuiService.MenuIsOpen end)
            blocked=blocked or (ok and opened==true)
        end
        local crouched,crouchSource,emote,emoteSource=stateSignals(t)
        local contact=grid:Sample(t,valid and enabled and not blocked and (movementTouch~=nil or jump:hasIntent(t)))
        local vx,vy,vz=0,0,0
        if valid then
            local velocity=root.AssemblyLinearVelocity
            vx,vy,vz=velocity.X,velocity.Y,velocity.Z
        end
        local speed=math.sqrt(vx*vx+vz*vz)
        local forwardDot=0
        local camera=services.Workspace.CurrentCamera
        if camera and speed>0.001 then
            local forward=camera.CFrame.LookVector
            local length=math.sqrt(forward.X*forward.X+forward.Z*forward.Z)
            if length>0.001 then forwardDot=(vx*forward.X+vz*forward.Z)/(speed*length) end
        end
        local canJump=true
        if valid then
            local ok,value=pcall(function() return humanoid:GetStateEnabled(Enum.HumanoidStateType.Jumping) end)
            if ok then canJump=value end
        end
        return {alive=valid and true or false,grounded=grounded,blocked=blocked and true or false,
            nativeState=state,crouched=crouched,crouchSource=crouchSource,emote=emote,emoteSource=emoteSource,
            horizontalSpeed=speed,verticalSpeed=vy,forwardDot=forwardDot,canJump=canJump,
            gridContact=contact.contact,gridNearby=contact.nearby,gridEvidence=contact.evidence,
            gridPart=contact.part and contact.part:GetFullName() or nil,gridAge=t-(contact.at or t),
            jumpIntent=jump:hasIntent(t)}
    end
    local function saveLayout()
        layoutSaved={}
        for name,object in pairs({joystick=presentation.joystick,jump=presentation.jump,knob=presentation.knob}) do
            layoutSaved[name]={Position=object.Position,Size=object.Size,AnchorPoint=object.AnchorPoint,
                attributes=object:GetAttributes()}
        end
    end
    local function maintain(t)
        if t-lastMaintenance<0.25 then return end
        lastMaintenance=t
        if not route.running then route:Start() else route:Refresh() end
        if route:IsReady() and routeGeneration~=route.generation then
            routeGeneration=route.generation
            replayPending=true
            event("keyboard_route_reactivated",{generation=routeGeneration})
        end
        gate:Refresh()
        for track in pairs(tracks) do if not track.IsPlaying then tracks[track]=nil end end
        if not presentation.gui.Parent or not presentation.joystick.Parent or not presentation.jump.Parent
            or not presentation.knob.Parent then
            clearInput()
            presentation:Stop(false)
            presentation=modules.Controls.new(services)
            for name,saved in pairs(layoutSaved) do
                local object=presentation[name]
                object.Position,object.Size,object.AnchorPoint=saved.Position,saved.Size,saved.AnchorPoint
                for key,value in pairs(saved.attributes) do object:SetAttribute(key,value) end
            end
            event("overlay_recreated")
        else
            local camera=services.Workspace.CurrentCamera
            if camera then presentation:Layout(camera.ViewportSize) end
            saveLayout()
        end
    end
    local function update(dt)
        if not running then return end
        local started=now()
        -- InputEnded can be missed while the app loses focus or controllers reset.
        -- Reconcile the actual InputObject state before issuing any held input.
        for input in pairs(controlTouches) do
            if input.UserInputState==Enum.UserInputState.End or input.UserInputState==Enum.UserInputState.Cancel then
                releaseTouch(input,input.UserInputState==Enum.UserInputState.Cancel)
            end
        end
        maintain(started)
        local observed=observe(started)
        if not observed.alive or observed.blocked then clearInput() end
        local result=policy:step({active=movementTouch~=nil,x=analogX,z=analogZ},observed,started)
        -- Revalidate current body contact at the exact opportunity to request a
        -- buffered native jump. Cached discovery never grants an air/nearby hop.
        local jumpObserved={alive=observed.alive,blocked=observed.blocked,grounded=observed.grounded,
            canJump=observed.canJump,gridContact=false}
        if observed.grounded and jump:hasIntent(started) and not jump.spentGround
            and started-jump.lastPulse>=0.11 then
            jumpObserved.gridContact=grid:ContactNow(started).contact
        end
        local space,reason=jump:step(started,jumpObserved)
        result.keys.Space=space
        if replayPending then
            -- Keyboard:Enable resets its directional fields. Replay held edges
            -- after activation, retrying failed releases before claiming success.
            ledger:apply({})
            replayPending=Core.chord(ledger.pressed)~="-"
            if replayPending then result.keys={} end
        end
        local chord=ledger:apply(result.keys)
        if chord~=lastChord then
            changes=changes+1
            event("input_changed",{from=lastChord,to=chord,state=result.primary,x=analogX,z=analogZ})
            lastChord=chord
        end
        if reason then event("native_jump_request",{reason=reason,grounded=observed.grounded,
            realGridContact=jumpObserved.gridContact,acceptedByGame="unconfirmed"}) end
        if log.enabled and started-lastLog>=0.10 then
            lastLog=started
            event("sample",{state=result.primary,flags=result.flags,chord=chord,x=analogX,z=analogZ,
                horizontal=observed.horizontalSpeed,vertical=observed.verticalSpeed,
                grid=observed.gridContact,nearby=observed.gridNearby,evidence=observed.gridEvidence,
                part=observed.gridPart,crouchSource=observed.crouchSource,emoteSource=observed.emoteSource})
            if lastSpeed and lastSpeed-observed.horizontalSpeed>6
                and observed.horizontalSpeed<lastSpeed*0.82 then
                event("speed_drop",{before=lastSpeed,after=observed.horizontalSpeed,
                    interval=started-lastSpeedTime,chord=chord,state=result.primary,
                    route=route.status,transportFailures=ledger.failures,ourPhysicsWrites=0,
                    cause="unattributed: game physics, input response or another script"})
            end
            lastSpeed,lastSpeedTime=observed.horizontalSpeed,started
        end
        presentation:Step(dt)
        lastResult,lastObservation=result,observed
        ticks=ticks+1
        maxTickMS=math.max(maxTickMS,(now()-started)*1000)
    end
    local function move(position)
        if not movementCenter then return end
        local point=Vector2.new(position.X,position.Y)
        local delta=point-movementCenter
        analogX,analogZ=delta.X/movementRadius,delta.Y/movementRadius
        presentation:SetKnob(delta)
    end
    local api={Version="rebuild-1.0-native-input"}
    local function guardedUpdate(dt)
        local ok,message=pcall(update,dt)
        if not ok then
            event("runtime_error",{message=tostring(message)})
            pcall(clearInput)
            pcall(api.Stop,true)
            warn("[PC Movement Rebuild] Stopped after runtime error: "..tostring(message))
        end
        return ok,message
    end
    function api.GetState()
        return {version=api.Version,enabled=enabled,running=running,chord=Core.chord(ledger.pressed),
            state=lastResult and lastResult.primary or "STARTING",flags=lastResult and lastResult.flags or {},
            analogX=analogX,analogZ=analogZ,observation=lastObservation,
            route=route:GetState(),cameraMethods=gate.methods,diagnostics=log.enabled,
            counters={ticks=ticks,keyEvents=ledger.events,keyFailures=ledger.failures,jumpPulses=jump.pulses,
                inputChanges=changes,broadQueries=grid.queries,narrowReads=grid.narrowReads,maxTickMS=maxTickMS},
            oldCleanupErrors=cleanupErrors,physicsWrites=0}
    end
    function api.SetEnabled(value)
        enabled=value~=false
        clearInput()
        route:SetEnabled(enabled)
        guardedUpdate(0)
        return enabled
    end
    function api.IsEnabled() return enabled and running end
    function api.SetSwapAD(value) config.SwapAD=value==true guardedUpdate(0) end
    function api.SetStateProvider(fn)
        assert(fn==nil or type(fn)=="function","StateProvider must be a function or nil")
        provider=fn;guardedUpdate(0)
    end
    function api.SetDiagnostics(value) log.enabled=value==true return log.enabled end
    function api.GetLogs() return log:read() end
    function api.Probe()
        local result={state=api.GetState(),attributes={},boolValues={},animations={}}
        for _,object in ipairs({player,character or false,humanoid or false}) do
            if object then result.attributes[object.Name]=object:GetAttributes() end
        end
        for name,object in pairs(valueObjects) do
            if object.Parent then result.boolValues[name]=object.Value end
        end
        for track in pairs(tracks) do
            if track.IsPlaying and track.Animation then
                result.animations[#result.animations+1]={name=track.Name,id=track.Animation.AnimationId}
            end
        end
        return result
    end
    function api.ExportDiagnostics(filename)
        local payload={probe=api.Probe(),events=log:read()}
        local json=services.HttpService:JSONEncode(payload)
        filename=filename or "PCMovementRebuild_Log.json"
        if type(writefile)=="function" then
            local ok,message=pcall(writefile,filename,json)
            if not ok then return false,tostring(message),json end
            return true,filename
        end
        return false,"writefile unavailable",json
    end
    function api.Stop(retainUI)
        if not running then return end
        running=false
        clearInput()
        disconnect(connections);disconnect(charConnections)
        run:UnbindFromRenderStep(BIND)
        gate:Stop();grid:Stop();route:Stop()
        ledger:apply({})
        if Core.chord(ledger.pressed)~="-" then
            env.__PCMovementPendingRelease=ledger.pressed
            warn("[PC Movement Rebuild] Key release failed; retained for next start.")
        end
        presentation:Stop(retainUI==true)
        for _,name in ipairs({"PCMovementRebuild","PCModeLock","PCKeyboardTouchBridgeV52",
            "LegacyGridContactAssistV1","__PCModeLockCleanup","__PCKeyboardTouchBridgeV52Cleanup",
            "__LegacyGridContactAssistV1Cleanup"}) do
            if name=="PCMovementRebuild" then
                if env[name]==api then env[name]=nil end
            elseif env.PCMovementRebuild==nil then env[name]=nil end
        end
    end
    connect(player.CharacterAdded,bindCharacter)
    connect(player.CharacterRemoving,function() bindCharacter(nil) end)
    connect(uis.InputBegan,function(input)
        if not running or not enabled or not focused or input.UserInputType~=Enum.UserInputType.Touch
            or uis:GetFocusedTextBox() then return end
        local control=presentation:Contains(input.Position)
        if control=="joystick" and not movementTouch then
            movementTouch=input;controlTouches[input]=true
            movementCenter=presentation.joystick.AbsolutePosition+presentation.joystick.AbsoluteSize/2
            movementRadius=math.max(46,math.min(presentation.joystick.AbsoluteSize.X,
                presentation.joystick.AbsoluteSize.Y)*0.42)
            move(input.Position);guardedUpdate(0)
        elseif control=="jump" then
            jumpTouches[input]=true;controlTouches[input]=true
            jump:setHeld(true,now());presentation:SetJumpPressed(true);guardedUpdate(0)
        end
    end)
    connect(uis.InputChanged,function(input)
        if controlTouches[input] then
            if input.UserInputState==Enum.UserInputState.Cancel or input.UserInputState==Enum.UserInputState.End then
                releaseTouch(input,input.UserInputState==Enum.UserInputState.Cancel)
            elseif input==movementTouch then move(input.Position) end
            guardedUpdate(0)
        end
    end)
    connect(uis.InputEnded,function(input)
        if controlTouches[input] then
            releaseTouch(input,input.UserInputState==Enum.UserInputState.Cancel)
            guardedUpdate(0)
        end
    end)
    connect(uis.WindowFocusReleased,function() focused=false clearInput() end)
    connect(uis.WindowFocused,function() focused=true clearInput() end)
    connect(uis.TextBoxFocused,clearInput)
    local initialized,message=pcall(function()
        route:Start()
        bindCharacter(player.Character)
        saveLayout()
        run:BindToRenderStep(BIND,Enum.RenderPriority.Input.Value-2,guardedUpdate)
        update(0)
    end)
    if not initialized then
        pcall(api.Stop,true)
        error("[PC Movement Rebuild] Initialization rolled back: "..tostring(message))
    end
    -- Publish only a fully initialized runtime. Failure paths release their
    -- listeners, route and keys through the same idempotent Stop.
    env.PCMovementRebuild=api
    env.PCModeLock={Version=api.Version,SetEnabled=api.SetEnabled,IsEnabled=api.IsEnabled,GetState=api.GetState}
    env.PCKeyboardTouchBridgeV52={Version=api.Version,GetState=function()
        local keys={}
        for _,name in ipairs({"W","A","S","D"}) do keys[name]=ledger.pressed[name] end
        return {chord=Core.chord(keys),analogX=analogX,analogZ=analogZ,
            movementTouchActive=movementTouch~=nil,movementTouch=movementTouch,
            keyEvents=ledger.events,jumpPulses=jump.pulses,sweepActive=false,
            directPlayerMove=false,visibleJoystick=true}
    end}
    env.LegacyGridContactAssistV1={Version=api.Version,GetState=function()
        return {contact=lastObservation and lastObservation.gridContact or false,physicsWrites=0}
    end}
    env.__PCModeLockCleanup=api.Stop
    env.__PCKeyboardTouchBridgeV52Cleanup=api.Stop
    env.__LegacyGridContactAssistV1Cleanup=api.Stop
    return api
end
return Runtime

end

local modules = {

    Core = buildCore(),

    KeyboardRoute = buildKeyboardRoute(),

    Controls = buildControls(),

    GridSensor = buildGridSensor(),

    CameraGate = buildCameraGate(),

    Runtime = buildRuntime(),

}
if not game:IsLoaded() then game.Loaded:Wait() end
local players=game:GetService("Players")
if not players.LocalPlayer then players:GetPropertyChangedSignal("LocalPlayer"):Wait() end
return modules.Runtime.Start(modules,getgenv().PCMovementRebuildConfig or {})
